      starter: "LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]\n\n\ndef new_board():\n    return [\" \"] * 9\n\n\ndef show(board):\n    rows = [\" \" + \" | \".join(board[i:i + 3]) for i in (0, 3, 6)]\n    return \"\\n---+---+---\\n\".join(rows)\n\n\ndef place(board, cell, mark):\n    if not 1 <= cell <= 9:\n        raise ValueError(\"Pick a cell from 1 to 9\")\n    if board[cell - 1] != \" \":\n        raise ValueError(\"That cell is taken\")\n    board[cell - 1] = mark\n\n\ndef free_cells(board):\n    return [i + 1 for i, value in enumerate(board) if value == \" \"]\n\n\ndef winner(board):\n    for a, b, c in LINES:\n        if board[a] != \" \" and board[a] == board[b] == board[c]:\n            return board[a]\n    return None\n\n\ndef game_over(board):\n    return winner(board) is not None or not free_cells(board)\n\n\ndef parse_move(text):\n    try:\n        cell = int(text.strip())\n    except ValueError:\n        raise ValueError(\"Type a number from 1 to 9\")\n    if not 1 <= cell <= 9:\n        raise ValueError(\"Type a number from 1 to 9\")\n    return cell\n\n\ndef other(mark):\n    return \"O\" if mark == \"X\" else \"X\"\n\n\ndef simple_move(board, mark):\n    for target in (mark, other(mark)):          # first win, then block\n        for cell in free_cells(board):\n            board[cell - 1] = target\n            found = winner(board) == target\n            board[cell - 1] = \" \"\n            if found:\n                return cell\n    for cell in (5, 1, 3, 7, 9, 2, 4, 6, 8):     # centre, corners, edges\n        if board[cell - 1] == \" \":\n            return cell\n    return None\n\n\ndef threats(board, mark):\n    cells = []\n    for cell in free_cells(board):\n        board[cell - 1] = mark\n        if winner(board) == mark:\n            cells.append(cell)\n        board[cell - 1] = \" \"\n    return cells\n",
      hint: "Base cases: someone has won (1 or -1), or the board is full (0). Put each mark back to `\" \"` after trying it.",
      solution: "LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]\n\n\ndef new_board():\n    return [\" \"] * 9\n\n\ndef show(board):\n    rows = [\" \" + \" | \".join(board[i:i + 3]) for i in (0, 3, 6)]\n    return \"\\n---+---+---\\n\".join(rows)\n\n\ndef place(board, cell, mark):\n    if not 1 <= cell <= 9:\n        raise ValueError(\"Pick a cell from 1 to 9\")\n    if board[cell - 1] != \" \":\n        raise ValueError(\"That cell is taken\")\n    board[cell - 1] = mark\n\n\ndef free_cells(board):\n    return [i + 1 for i, value in enumerate(board) if value == \" \"]\n\n\ndef winner(board):\n    for a, b, c in LINES:\n        if board[a] != \" \" and board[a] == board[b] == board[c]:\n            return board[a]\n    return None\n\n\ndef game_over(board):\n    return winner(board) is not None or not free_cells(board)\n\n\ndef parse_move(text):\n    try:\n        cell = int(text.strip())\n    except ValueError:\n        raise ValueError(\"Type a number from 1 to 9\")\n    if not 1 <= cell <= 9:\n        raise ValueError(\"Type a number from 1 to 9\")\n    return cell\n\n\ndef other(mark):\n    return \"O\" if mark == \"X\" else \"X\"\n\n\ndef simple_move(board, mark):\n    for target in (mark, other(mark)):          # first win, then block\n        for cell in free_cells(board):\n            board[cell - 1] = target\n            found = winner(board) == target\n            board[cell - 1] = \" \"\n            if found:\n                return cell\n    for cell in (5, 1, 3, 7, 9, 2, 4, 6, 8):     # centre, corners, edges\n        if board[cell - 1] == \" \":\n            return cell\n    return None\n\n\ndef threats(board, mark):\n    cells = []\n    for cell in free_cells(board):\n        board[cell - 1] = mark\n        if winner(board) == mark:\n            cells.append(cell)\n        board[cell - 1] = \" \"\n    return cells\n\n\n_scores = {}\n\n\ndef score(board, turn, me):\n    \"\"\"How the game ends for `me` with perfect play: 1 win, 0 draw, -1 loss.\"\"\"\n    key = (tuple(board), turn, me)\n    if key in _scores:\n        return _scores[key]\n    won = winner(board)\n    if won is not None:\n        result = 1 if won == me else -1\n    elif not free_cells(board):\n        result = 0\n    else:\n        results = []\n        for cell in free_cells(board):\n            board[cell - 1] = turn\n            results.append(score(board, other(turn), me))\n            board[cell - 1] = \" \"\n        result = max(results) if turn == me else min(results)\n    _scores[key] = result\n    return result\n\n\ndef best_move(board, mark):\n    best_cell, best_score = None, -2\n    for cell in free_cells(board):\n        board[cell - 1] = mark\n        result = score(board, other(mark), mark)\n        board[cell - 1] = \" \"\n        if result > best_score:\n            best_cell, best_score = cell, result\n    return best_cell\n",
